sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var testContacts = [
        { Id: '003dN00000UxZ25QAF', FirstName: 'RAYAN', LastName: 'FAIZ', Name: 'RAYAN FAIZ', Email: 'rayan.faiz@avatu.in', Phone: '9000000001', Title: 'Purchase Manager', AccountId: '001dN000011ZtlJQAS' },
        { Id: '003dN00000UxZYLQA3', FirstName: 'Sneha', LastName: 'Mallavelli', Name: 'Sneha Mallavelli', Email: 'snehamallavelli123@gmail.com', Phone: '9000000003', Title: 'ICU Head', AccountId: '001dN000011ZtlJQAS' },
        { Id: '003dN00000UxZQHQA3', FirstName: 'Manjunath', LastName: 'Reddy', Name: 'Manjunath Reddy', Email: 'manjunath.reddy@avatu.in', Phone: '9000000002', Title: 'Finance Approver', AccountId: '001dN000011ZtlJQAS' }
    ];

    // Create import set for contacts
    var importSet = new GlideRecord('sys_import_set');
    importSet.initialize();
    importSet.setValue('table_name', 'x_1775706_salesfor_sf_ctct_stg');
    importSet.setValue('state', 'loaded');
    var importSetId = importSet.insert();

    // Insert staging rows
    for (var i = 0; i < testContacts.length; i++) {
        var ctct = testContacts[i];
        var row = new GlideRecord('x_1775706_salesfor_sf_ctct_stg');
        row.initialize();
        row.setValue('sys_import_set', importSetId);
        row.setValue('sys_import_state', 'pending');
        row.setValue('u_id', ctct.Id);
        row.setValue('u_firstname', ctct.FirstName);
        row.setValue('u_lastname', ctct.LastName);
        row.setValue('u_name', ctct.Name);
        row.setValue('u_email', ctct.Email);
        row.setValue('u_phone', ctct.Phone);
        row.setValue('u_title', ctct.Title);
        row.setValue('u_accountid', ctct.AccountId);
        row.insert();
    }

    // Run the contact transform
    var isGr = new GlideRecord('sys_import_set');
    isGr.get(importSetId);
    var transformer = new GlideImportSetTransformer();
    transformer.transformAllMaps(isGr);

    // Verify RAYAN FAIZ contact
    var rayan = new GlideRecord('x_1775706_salesfor_sf_contact');
    rayan.addQuery('x_1775706_salesf_1_salesforce_id', '003dN00000UxZ25QAF');
    rayan.query();
    assertEqual({ name: 'RAYAN FAIZ contact created', shouldbe: true, value: rayan.hasNext() });
    if (rayan.next()) {
        assertEqual({ name: 'First name = RAYAN', shouldbe: 'RAYAN', value: rayan.getValue('first_name') });
        assertEqual({ name: 'Last name = FAIZ', shouldbe: 'FAIZ', value: rayan.getValue('last_name') });
        assertEqual({ name: 'Email mapped', shouldbe: 'rayan.faiz@avatu.in', value: rayan.getValue('email') });
        assertEqual({ name: 'Title = Purchase Manager', shouldbe: 'Purchase Manager', value: rayan.getValue('title') });
        // Verify account reference resolved
        var acctRef = rayan.getValue('account');
        assertEqual({ name: 'Contact has account reference', shouldbe: true, value: (acctRef !== '' && acctRef !== null) });
    }

    // Verify all 3 contacts imported
    var countGr = new GlideRecord('x_1775706_salesfor_sf_contact');
    countGr.addQuery('x_1775706_salesf_1_salesforce_idSTARTSWITH003dN000');
    countGr.query();
    var importedCount = countGr.getRowCount();
    assertEqual({ name: 'All 3 contacts imported', shouldbe: 3, value: importedCount });

    // Verify Sneha
    var sneha = new GlideRecord('x_1775706_salesfor_sf_contact');
    sneha.addQuery('x_1775706_salesf_1_salesforce_id', '003dN00000UxZYLQA3');
    sneha.query();
    assertEqual({ name: 'Sneha Mallavelli contact created', shouldbe: true, value: sneha.hasNext() });

    // Verify Manjunath
    var manjunath = new GlideRecord('x_1775706_salesfor_sf_contact');
    manjunath.addQuery('x_1775706_salesf_1_salesforce_id', '003dN00000UxZQHQA3');
    manjunath.query();
    assertEqual({ name: 'Manjunath Reddy contact created', shouldbe: true, value: manjunath.hasNext() });

    outputs.ctct_import_set_id = importSetId.toString();
    stepResult.setOutputMessage('Staged and transformed 3 contacts. All linked to Apollo account.');
})(outputs, steps, params, stepResult, assertEqual);

